 const release=mountReleaseControls(root);get('videoRecommendations').onclick=()=>openRecommendationControls({modal,toast});
 const draftMode=()=>{const episode=get('draftKind').value==='episode';for(const id of ['draftSeriesLabel','draftSeasonLabel','draftEpisodeLabel'])get(id).hidden=!episode;get('draftSeries').required=episode;for(const name of ['seasonNumber','episodeNumber'])get('videoDraft').elements[name].required=episode;if(episode&&titles.find(t=>t.id===select.value)?.kind==='series')get('draftSeries').value=select.value;};get('draftKind').onchange=draftMode;draftMode();
