  for(const title of titles)select.add(new Option(`${title.kind==='episode'?(title.series_name+' · S'+title.season_number+' E'+title.episode_number+' · '):title.kind==='series'?'Series · ':'Movie · '}${title.name} · ${title.status}${title.published_at?' · '+new Date(title.published_at).toLocaleString():''}`,title.id));
